def esc(s):return html.escape(s,quote=True)
def link(page,label,cls='text-link'):return f'<a class="{cls}" href="{page}">{label}</a>'
def buttons(primary='Request a technical briefing',target='contact.html',secondary=None):
 return '<div class="actions">'+link(target,primary,'button light')+(link(secondary[0],secondary[1],'button outline') if secondary else '')+'</div>'
def brand():return f'<a class="brand" href="index.html" aria-label="R4 Aerospace and Defence — Home"><img src="{logo}" width="52" height="52" alt=""><span><strong>R4 Aerospace &amp; Defence</strong><small>Integrated Earth Intelligence</small></span></a>'
