def workflow():
 names=[('Define','Specify the area, observation window and analytical question.'),('Observe','Coordinate complementary measurements of the same event.'),('Correlate','Align geometry, timestamps and calibration metadata.'),('Assess','Evaluate detections, change, confidence and uncertainty.'),('Deliver','Provide traceable evidence for authorised human assessment.')]
