FAQ=[('What is R4 developing?','A synchronised multimodal Earth-observation architecture and analytical platform intended to support defence, civil and commercial decision-making.'),('What is Insight Set™?','The proposed coordinated formation of one microsatellite and two CubeSats, with complementary sensing and distributed processing responsibilities.'),('Why does acquisition timing matter?','Dynamic scenes change between observations. Reducing acquisition offsets can improve correlation, provided spatial registration, calibration and observation geometry are also addressed.'),('Is the satellite service operational?','R4’s published roadmap describes system development and a target pathfinder window of Q4 2027–Q1 2028. This website presents the development programme rather than an operational service commitment.'),('Can every sensor observe through clouds?','No. Radar can acquire useful measurements through cloud cover in many conditions. Optical and thermal-infrared observations remain sensitive to atmospheric transmission and other scene-specific constraints.'),('What does ℝ Analytics aim to provide?','Observation alignment, modality comparison, change and anomaly assessment, geospatial outputs and reports that retain provenance and uncertainty information.'),('How can an institution collaborate?','Through application studies, validation programmes, research collaboration, payload and subsystem partnerships, platform integration or investment discussions.')]
PAGES['company']=('Company','R4 Aerospace & Defence: research-led development of distributed satellite sensing and multimodal Earth intelligence.',pagehero('Company','Research-led engineering.<br>Mission-oriented development.','R4 Aerospace & Defence Private Limited is an Indian enterprise developing coordinated satellite observation and analytical systems for defence, civil, environmental and commercial applications.',[('mission','Mission'),('leadership','Leadership'),('roadmap','Development roadmap'),('faq','Frequently asked questions')])+
section('Mission and vision','Reduce the interval between<br>observation and informed action.','Our development programme connects distributed spacecraft engineering, sensing science and analytical software.',cards([('MISSION','Evidence-based Earth intelligence','Develop coherent, traceable observation products that help institutions interpret time-sensitive events.','',''),('VISION','Integrated observation infrastructure','Progress towards scalable multimodal intelligence for sovereign, environmental and commercial applications.','',''),('METHOD','Progressive technical validation','Use simulation, engineering models, representative datasets and mission studies to evaluate feasibility and performance.','','')]),'white','mission')+
'<section class="section" id="leadership"><div class="wrap split"><div class="profile"><div class="monogram" aria-hidden="true">KT</div><span class="eyebrow">Founder</span><h3>Dr. Kathiravan Thangavel</h3><p class="role">Aerospace systems &amp; technical strategy</p><p>Leads R4’s technical and institutional direction, connecting distributed satellite systems, remote sensing, autonomy and analytical software.</p>'+link('contact.html?topic=Research%20collaboration','Discuss research collaboration')+'</div><div><span class="eyebrow">Interdisciplinary development</span><h2>Systems engineering<br>across the observation chain.</h2><p>Spacecraft and mission engineering establishes the architecture, interfaces and verification approach. Remote-sensing science connects measured signals with interpretable information.</p><p>Analytical software and institutional collaboration translate these capabilities into application-specific evidence and validation requirements.</p>'+link('careers.html','Explore research and engineering disciplines')+'</div></div></section>'+
section('Development roadmap','Progressive maturation<br>towards orbital demonstration.','Published target stages are contingent on financing, procurement, qualification, launch availability and applicable approvals.','<div class="timeline">'+''.join(f'<article><time>{a}</time><h3>{b}</h3><p>{c}</p></article>' for a,b,c in ROAD)+'</div>','white','roadmap')+
section('Engineering principles','Resilient. Responsive.<br>Real-time. Reconnaissance.','R4’s identity expresses development priorities rather than unconditional performance guarantees.',cards([('RESILIENT','Distributed capability','Assess redundancy, interdependence and recovery pathways at system level.','',''),('RESPONSIVE','Mission-driven planning','Align observation priorities with application requirements and available resources.','',''),('REAL-TIME','Reduced processing latency','Develop onboard and ground-processing workflows to reduce time to assessment.','',''),('RECONNAISSANCE','Corroborated observation','Combine complementary measurements with contextual and temporal information.','','')],'four'))+
section('Frequently asked questions','Technology and programme context.','Explore the architecture, development status and collaboration pathways.','<div class="faq-tools"><label for="faq-search">Search questions</label><input type="search" id="faq-search" placeholder="Search by keyword"><p id="faq-count" class="results-count" aria-live="polite">7 matching questions</p></div><div class="faq-list">'+''.join('<details><summary>'+a+'</summary><p>'+b+'</p></details>' for a,b in FAQ)+'</div><p class="no-results" id="faq-empty" hidden>No matching questions. Try a different keyword.</p>','white','faq')+cta('Contribute to the next stage of development.','Discuss an institutional partnership, research collaboration or technical contribution.'))
